<?php
namespace App\Services;
final class BarcodeService {
 public static function normalize(string $code):?string{$code=preg_replace('/\D/','',$code);if(strlen($code)===12){$sum=0;for($i=0;$i<12;$i++)$sum+=(int)$code[$i]*(($i%2===0)?1:3);$code.=(string)((10-($sum%10))%10);}if(strlen($code)!==13)return null;$sum=0;for($i=0;$i<12;$i++)$sum+=(int)$code[$i]*(($i%2===0)?1:3);if(((10-($sum%10))%10)!==(int)$code[12])return null;return$code;}
 public static function ean13Svg(string $input,int $module=2,int $height=70):string{$code=self::normalize($input);if(!$code)return'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="100"><text x="10" y="45" font-family="Arial" font-size="16">Code-barres EAN-13 invalide</text><text x="10" y="70" font-family="Arial" font-size="14">'.htmlspecialchars($input,ENT_QUOTES).'</text></svg>';$L=['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'];$G=['0100111','0110011','0011011','0100001','0011101','0111001','0000101','0010001','0001001','0010111'];$R=['1110010','1100110','1101100','1000010','1011100','1001110','1010000','1000100','1001000','1110100'];$P=['LLLLLL','LLGLGG','LLGGLG','LLGGGL','LGLLGG','LGGLLG','LGGGLL','LGLGLG','LGLGGL','LGGLGL'];$bits='101';$par=$P[(int)$code[0]];for($i=1;$i<=6;$i++){$d=(int)$code[$i];$bits.=$par[$i-1]==='L'?$L[$d]:$G[$d];}$bits.='01010';for($i=7;$i<=12;$i++)$bits.=$R[(int)$code[$i]];$bits.='101';$quiet=10;$w=(strlen($bits)+$quiet*2)*$module;$svg='<svg xmlns="http://www.w3.org/2000/svg" width="'.$w.'" height="'.($height+28).'" viewBox="0 0 '.$w.' '.($height+28).'" role="img"><rect width="100%" height="100%" fill="white"/>';$x=$quiet*$module;for($i=0,$n=strlen($bits);$i<$n;$i++)if($bits[$i]==='1')$svg.='<rect x="'.($x+$i*$module).'" y="2" width="'.$module.'" height="'.$height.'" fill="black"/>';$svg.='<text x="'.($w/2).'" y="'.($height+20).'" text-anchor="middle" font-family="Arial" font-size="14" letter-spacing="2">'.$code.'</text></svg>';return$svg;}
}
